// ── Input ─────────────────────────────────────────────────────────────────
const body = ($input.first().json.body) || {};
const raw  = (body.message || '').trim();
const msg  = raw.toLowerCase();
const ctx  = body.context || {};
const page = (body.page || '').toLowerCase();

// ── Intent keywords (priority order) ──────────────────────────────────────
const INTENT_KW = [
  { intent: 'FORMATION_SIMULATION', kw: ['si je forme','si je formais','simuler formation','impact formation','si elle suivait','si il suivait','formation sur','apres formation','après formation','si on formait'] },
  { intent: 'SUCCESSION',           kw: ['remplaçant','remplacer','succession','successeur','backup','départ de','qui remplace','qui peut remplacer','plan de succession','candidat successeur'] },
  { intent: 'TALENT',               kw: ['haut potentiel','hauts potentiels','high potential','hipo','top talent','top talents','nine box','9 box','fort potentiel','meilleur profil','matrice talent'] },
  { intent: 'PROMOTION',            kw: ['promotion','promouvable','prêt à évoluer','prête à évoluer','readiness','monter en grade','passer senior','passer manager','évoluer','qui mérite','accéder à'] },
  { intent: 'POSTES_CRITIQUES',     kw: ['sans successeur','poste critique','poste à risque','risque succession','risque rh','vulnérabilité','position critique'] },
  { intent: 'FORMATION',            kw: ['formation','certification','développement','compétence manquante','apprendre','se former','parcours','plan de développement','coursera','udemy'] },
  { intent: 'ANALYTICS',            kw: ['statistique','stats','kpi','effectif','répartition','tableau de bord','combien','taux','distribution','dashboard','insights rh'] }
];

// ── Page context default ───────────────────────────────────────────────────
let intent = 'ANALYTICS';
if (page.includes('succession'))    intent = 'SUCCESSION';
else if (page.includes('talent'))   intent = 'TALENT';
else if (page.includes('formation')) intent = 'FORMATION';

// ── Follow-up detection ────────────────────────────────────────────────────
const followUpKw = [
  'et lui','et elle','et son','et ses','pourquoi lui','pourquoi elle',
  'et son readiness','et ses formations','le même','et ses compétences',
  'et la succession','son remplaçant'
];
const isFollowUp = followUpKw.some(kw => msg.includes(kw));
if (isFollowUp && ctx.lastIntent) {
  intent = ctx.lastIntent;
} else {
  for (const { intent: i, kw } of INTENT_KW) {
    if (kw.some(k => msg.includes(k))) { intent = i; break; }
  }
}

// ── Name extraction (requires >= 2 tokens) ────────────────────────────────
function normalizeToken(token) {
  return String(token || '').replace(/^[^A-Za-zÀ-ÿ'-]+|[^A-Za-zÀ-ÿ'-]+$/g, '').trim();
}

function detectName(text) {
  const stop = new Set([
    'qui','quel','quelle','quels','quelles','est','ce','que','pour','une','un',
    'la','le','les','des','du','de','d','si','je','il','elle','ils','elles',
    'vous','nous','mon','ma','son','ses','mes','leur','leurs',
    'forme','formais','peut','remplace','remplacer','remplaçant','succession',
    'successeur','prêt','prête','promotion','promouvable','readiness','formation',
    'niveau','sur','en','après','apres','impact','simuler','senior','manager',
    'director','partner','poste','avec','sans','dans','par','ou','et',
    'est-il','est-elle','comment'
  ]);
  const connectors = new Set(['ben','bin','bint','ibn','el','al','ould']);
  const tokens = String(text || '').replace(/[?!.,;:()\[\]]/g, ' ').split(/\s+/).filter(Boolean);
  const sequences = [];
  let current = [];

  const flush = () => {
    if (current.length >= 2) sequences.push(current.slice());
    current = [];
  };

  for (const token of tokens) {
    const clean = normalizeToken(token);
    if (!clean) { flush(); continue; }
    const lower      = clean.toLowerCase();
    const startsUpper = /^[A-ZÀ-Ý]/.test(clean);
    const isConnector = connectors.has(lower);
    const isStop      = stop.has(lower);
    if ((startsUpper && !isStop) || (current.length > 0 && isConnector)) {
      current.push(clean);
    } else {
      flush();
    }
  }
  flush();
  return sequences.length > 0 ? sequences[0].slice(0, 4).join(' ') : null;
}

// ── Formation entity extraction ────────────────────────────────────────────
function detectFormationEntities(text) {
  const re1 = /(?:sur|en)\s+([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ\s&'-]{1,50}?)\s+(?:niveau|lvl|niv|level)\s+([1-5])/i;
  const re2 = /([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ\s&'-]{1,50}?)\s+(?:niveau|lvl|niv|level)\s+([1-5])/i;
  const m = text.match(re1) || text.match(re2);
  return m
    ? { competence: m[1].trim(), niveau: parseInt(m[2], 10) }
    : { competence: null, niveau: null };
}

// ── Poste cible extraction ─────────────────────────────────────────────────
function detectPosteCible(text) {
  const m = text.match(/(?:pour le poste de|pour le poste|au poste de)\s+([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ\s'-]{1,40}?)(?:\s*[?!,.]|$)/i);
  return m ? m[1].trim() : null;
}

// ── Entity resolution ──────────────────────────────────────────────────────
const needsName = new Set(['SUCCESSION', 'PROMOTION', 'FORMATION_SIMULATION']);
const rawName   = needsName.has(intent) ? detectName(raw) : null;
const resolvedName = rawName
  || (isFollowUp && ctx.lastCollaborateurNom ? ctx.lastCollaborateurNom : null);
const resolvedId = (isFollowUp && ctx.lastCollaborateurId)
  ? ctx.lastCollaborateurId
  : (body.contextId || null);

const { competence: detectedCompetence, niveau: detectedNiveau } =
  intent === 'FORMATION_SIMULATION'
    ? detectFormationEntities(raw)
    : { competence: null, niveau: null };

const detectedPoste = intent === 'FORMATION_SIMULATION' ? detectPosteCible(raw) : null;

// Validation FORMATION_SIMULATION
let finalIntent = intent;
if (intent === 'FORMATION_SIMULATION' && (!detectedCompetence || !detectedNiveau)) {
  finalIntent = 'FORMATION_SIM_INCOMPLETE';
}

return [{ json: {
  message:            raw,
  intent:             finalIntent,
  context:            ctx,
  contextId:          resolvedId,
  detectedName:       resolvedName,
  detectedCompetence,
  detectedNiveau,
  detectedPoste,
  isFollowUp
}}];

const di     = $input.first().json;
const BASE   = 'http://localhost:5000/api/chatbot';
const intent = di.intent;
const name   = di.detectedName;
const cid    = di.contextId;
const ctx    = di.context || {};

async function getJson(url) {
  let res, text;
  try {
    res  = await fetch(url, { method: 'GET', headers: { Accept: 'application/json' } });
    text = await res.text();
  } catch (e) {
    return { __networkError: true, url, message: String(e) };
  }
  let data = null;
  try { data = text ? JSON.parse(text) : null; } catch { data = { __parseError: true, raw: text }; }
  if (!res.ok) return { __httpError: true, status: res.status, url, body: data };
  return data;
}

async function findCollab(nom) {
  if (!nom) return { __notFound: true, nomRecherche: nom };
  const url  = BASE + '/find?nom=' + encodeURIComponent(nom);
  const data = await getJson(url);
  if (!data || data.__httpError || data.__networkError || !data.id) {
    return { __notFound: true, nomRecherche: nom, findUrl: url };
  }
  return data;
}

let result = {};

// ── SUCCESSION ─────────────────────────────────────────────────────────────
if (intent === 'SUCCESSION') {
  if (name) {
    const found = await findCollab(name);
    if (found.__notFound) {
      result = { __branch: 'SUCCESSION', __notFound: true, nomRecherche: name };
    } else {
      const data = await getJson(BASE + '/succession/' + found.id);
      result = Object.assign({}, data || {}, {
        __branch: 'SUCCESSION', __nominative: true,
        __findNom: found.nom, __findId: found.id
      });
    }
  } else if (cid) {
    const data = await getJson(BASE + '/succession/' + cid);
    result = Object.assign({}, data || {}, { __branch: 'SUCCESSION', __nominative: true });
  } else {
    const data = await getJson(BASE + '/postes-sans-successeur');
    result = Object.assign({}, data || {}, { __branch: 'SUCCESSION', __aggregate: true });
  }
}

// ── PROMOTION ──────────────────────────────────────────────────────────────
else if (intent === 'PROMOTION') {
  if (name) {
    const found = await findCollab(name);
    if (found.__notFound) {
      result = { __branch: 'PROMOTION', __notFound: true, nomRecherche: name };
    } else {
      const data = await getJson(BASE + '/promotion/' + found.id);
      result = Object.assign({}, data || {}, {
        __branch: 'PROMOTION', __nominative: true,
        id: found.id, nom: found.nom
      });
    }
  } else {
    const data = await getJson(BASE + '/promotables');
    result = Object.assign({}, data || {}, { __branch: 'PROMOTION', __aggregate: true });
  }
}

// ── TALENT ─────────────────────────────────────────────────────────────────
else if (intent === 'TALENT') {
  const data = await getJson(BASE + '/hr-talent');
  result = { __branch: 'TALENT', talents: Array.isArray(data) ? data : [] };
}

// ── FORMATION_SIMULATION ───────────────────────────────────────────────────
else if (intent === 'FORMATION_SIMULATION') {
  const competence = di.detectedCompetence;
  const niveau     = di.detectedNiveau;
  const posteMsg   = di.detectedPoste;

  if (!name) {
    result = { __branch: 'FORMATION_SIMULATION', __noName: true };
  } else {
    const found = await findCollab(name);
    if (found.__notFound) {
      result = { __branch: 'FORMATION_SIMULATION', __notFound: true, nomRecherche: name };
    } else {
      let posteCible = posteMsg || ctx.lastPoste || null;
      if (!posteCible) {
        const profile = await getJson(BASE + '/collaborateur/' + found.id);
        posteCible = (profile && !profile.__httpError && !profile.__networkError)
          ? (profile.poste || '') : '';
      }
      const simUrl = BASE + '/simulate-formation'
        + '?collaborateurId=' + found.id
        + '&posteCible='      + encodeURIComponent(posteCible || '')
        + '&competence='      + encodeURIComponent(competence || '')
        + '&niveauSimule='    + (niveau || 1);
      const data = await getJson(simUrl);
      result = Object.assign({}, data || {}, {
        __branch:           'FORMATION_SIMULATION',
        __nominative:       true,
        id:                 found.id,
        nom:                found.nom,
        posteCible,
        detectedCompetence: competence,
        detectedNiveau:     niveau
      });
    }
  }
}

// ── FORMATION_SIM_INCOMPLETE ───────────────────────────────────────────────
else if (intent === 'FORMATION_SIM_INCOMPLETE') {
  result = { __branch: 'FORMATION_SIM_INCOMPLETE' };
}

// ── POSTES_CRITIQUES ───────────────────────────────────────────────────────
else if (intent === 'POSTES_CRITIQUES') {
  const data = await getJson(BASE + '/postes-a-risque');
  result = Object.assign({}, data || {}, { __branch: 'POSTES_CRITIQUES' });
}

// ── FORMATION ─────────────────────────────────────────────────────────────
else if (intent === 'FORMATION') {
  const data = await getJson(BASE + '/stats');
  result = Object.assign({}, data || {}, { __branch: 'FORMATION' });
}

// ── ANALYTICS ─────────────────────────────────────────────────────────────
else if (intent === 'ANALYTICS') {
  const data = await getJson(BASE + '/stats');
  result = Object.assign({}, data || {}, { __branch: 'ANALYTICS' });
}

// ── FALLBACK ──────────────────────────────────────────────────────────────
else {
  result = { __branch: 'FALLBACK' };
}

return [{ json: result }];

const di     = $('Detect Intent + Extract Entities').first().json;
const data   = $input.first().json;
const intent = di.intent;
const ctx    = di.context || {};
const now    = new Date().toISOString();
const branch = data.__branch || intent;

// ── Execution history ──────────────────────────────────────────────────────
const prevHistory    = Array.isArray(ctx.executionHistory) ? ctx.executionHistory : [];
const execEntry      = { timestamp: now, intent, branch };
const executionHistory = [...prevHistory, execEntry].slice(-10);

const newCtx = Object.assign({}, ctx, { lastIntent: intent, executionHistory });

let answer = '', analysis = '', reasoning = [], actions = [], suggestions = [], sources = [], cards = [];

const toNum = (v, fb) => { const n = Number(v); return Number.isFinite(n) ? n : (fb !== undefined ? fb : 0); };

// ════════════════════════════════════════════════════════════════════════════
// SUCCESSION
// ════════════════════════════════════════════════════════════════════════════
if (branch === 'SUCCESSION') {

  if (data.__notFound) {
    answer    = 'Aucun collaborateur trouvé pour "' + (data.nomRecherche || '') + '". Vérifiez l\'orthographe (prénom + nom requis).';
    reasoning = ['Nom recherché : ' + (data.nomRecherche || '?'), 'GET /api/chatbot/find — aucune correspondance'];
    actions     = ['Vérifier l\'orthographe', 'Rechercher dans le répertoire RH'];
    suggestions = ['Quels postes sont sans successeur ?', 'Quels sont les hauts potentiels ?'];
    sources     = [{ label: 'GET /api/chatbot/find', type: 'api' }];

  } else if (data.__nominative && data.top3) {
    const top3     = data.top3 || [];
    const pipeline = data.candidatsEnAttente || [];
    const partant  = data.collaborateurNom || data.__findNom || 'ce collaborateur';

    answer   = top3.length > 0
      ? top3.length + ' successeur(s) identifié(s) pour ' + partant + '.'
      : 'Aucun successeur direct disponible pour ' + partant + '.';

    analysis = top3[0]
      ? 'Meilleur successeur : ' + top3[0].nom + ' (' + top3[0].grade + ', ' + top3[0].departement + ') — Score : ' + top3[0].scoreSuccession + '/100 — Couverture : ' + top3[0].scoreCouverture + '%.'
      : pipeline.length > 0 ? pipeline.length + ' candidat(s) en pipeline.' : 'Aucun profil compatible.';

    reasoning = [
      'Poste analysé : ' + (data.poste || ''),
      (data.competencesRequises || []).length + ' compétence(s) évaluée(s)',
      'Score pondéré : 60 % compétences + 15 % ancienneté + 15 % potentiel + 10 % transversal',
      top3.some(t => t.profilTransversal)
        ? 'Profil(s) transversal(aux) valorisé(s)'
        : 'Profils triés par score de succession'
    ];

    actions     = ['Voir le plan de succession complet', 'Exporter la comparaison PDF', 'Planifier un entretien'];
    suggestions = [
      'Quels postes sont sans successeur ?',
      top3[0] ? 'Quel est le readiness de ' + top3[0].nom + ' ?' : 'Montrez les postes à risque',
      'Quelles formations recommandez-vous ?'
    ];
    sources = [{ label: 'GET /api/chatbot/succession/' + (data.__findId || ''), type: 'api' }];

    cards = [{
      type: 'succession',
      data: {
        partant,
        poste:     data.poste,
        candidats: top3.map((c, i) => ({
          rank:                  i + 1,
          nom:                   c.nom,
          poste:                 c.poste,
          grade:                 c.grade,
          departement:           c.departement,
          scoreSuccession:       c.scoreSuccession,
          scoreCouverture:       c.scoreCouverture,
          competencesManquantes: c.competencesManquantes || [],
          profilTransversal:     c.profilTransversal,
          estEligible:           c.estEligible,
          delaiEstime: c.scoreSuccession >= 80 ? '3–6 mois'
                     : c.scoreSuccession >= 50 ? '6–12 mois' : '12–18 mois'
        })),
        pipeline: pipeline.slice(0, 3).map((c, i) => ({
          rank:            top3.length + i + 1,
          nom:             c.nom,
          grade:           c.grade,
          departement:     c.departement,
          scoreSuccession: c.scoreSuccession,
          scoreCouverture: c.scoreCouverture,
          estEligible:     c.estEligible
        }))
      }
    }];

    if (top3[0]) {
      newCtx.lastCollaborateurId  = data.__findId || top3[0].id || null;
      newCtx.lastCollaborateurNom = data.__findNom || top3[0].nom || null;
      newCtx.lastPoste            = data.poste || null;
      newCtx.lastGrade            = data.grade || null;
    }

  } else {
    const critiques = data.collaborateurs || [];
    answer = critiques.length > 0
      ? critiques.length + ' poste(s) sans successeur identifié(s).'
      : 'Tous les postes clés disposent d\'un successeur potentiel.';
    reasoning = [
      'Critère : aucun candidat éligible (NbCommunes > 0)',
      critiques.length + ' poste(s) en situation critique',
      critiques[0] ? 'Poste le plus exposé : ' + (critiques[0].nom || '') + ' — ' + (critiques[0].poste || '') : null
    ].filter(Boolean);
    actions     = ['Identifier des successeurs', 'Lancer un plan de développement', 'Voir les formations recommandées'];
    suggestions = ['Montrez les postes à risque', 'Quels sont les hauts potentiels ?'];
    sources     = [{ label: 'GET /api/chatbot/postes-sans-successeur', type: 'api' }];
    cards       = critiques.slice(0, 5).map(c => ({
      type: 'collaborateur', rank: null,
      data: { nom: c.nom, poste: c.poste, grade: c.grade, departement: c.departement, badge: 'Sans successeur', badgeLevel: 'critical' }
    }));
  }
}

// ════════════════════════════════════════════════════════════════════════════
// PROMOTION
// ════════════════════════════════════════════════════════════════════════════
else if (branch === 'PROMOTION') {
  const labelFromScore = s => s >= 80 ? 'Très prêt' : s >= 60 ? 'Prêt' : s >= 40 ? 'En développement' : 'Non éligible';
  const scoreSur5      = s => Math.round((s / 20) * 10) / 10;

  if (data.__notFound) {
    answer    = 'Aucun collaborateur trouvé pour "' + (data.nomRecherche || '') + '".';
    reasoning = ['Nom recherché : ' + (data.nomRecherche || '?'), 'GET /api/chatbot/find — introuvable'];
    actions     = ['Vérifier l\'orthographe', 'Lister les collaborateurs promouvables'];
    suggestions = ['Qui mérite une promotion ?', 'Quels sont les hauts potentiels ?'];
    sources     = [{ label: 'GET /api/chatbot/find', type: 'api' }];

  } else if (data.__nominative) {
    const score  = toNum(data.scorePromotion);
    const grade  = data.gradeActuel || data.grade || '';
    const cible  = data.gradeCible  || '';
    const detail = data.scoreDetail || {};
    const manq   = Array.isArray(data.competencesManquantes) ? data.competencesManquantes : [];
    const acq    = Array.isArray(data.competencesAcquises)   ? data.competencesAcquises   : [];

    answer   = (data.nom || '') + ' — readiness : ' + score + '/100 (' + labelFromScore(score) + ').';
    analysis = grade + (cible ? ' → ' + cible : '') + ' — délai estimé : ' + (data.delaiEstime || 'à confirmer') + '.';
    reasoning = [
      'Workflow nominatif : /find → /promotion/' + (data.id || ''),
      'Score global : ' + score + '/100',
      detail.competences != null ? 'Compétences : ' + detail.competences + '/100' : null,
      detail.performance != null ? 'Performance : '  + detail.performance  + '/100' : null,
      detail.potentiel   != null ? 'Potentiel : '    + detail.potentiel    + '/100' : null,
      detail.anciennete  != null ? 'Ancienneté : '   + detail.anciennete   + '/100' : null,
      manq.length ? 'Compétences manquantes : ' + manq.slice(0, 4).join(', ') : null,
      data.justificationRH || null
    ].filter(Boolean);
    actions     = ['Planifier un entretien de carrière', 'Voir le parcours carrière', 'Lancer un plan de développement ciblé'];
    suggestions = ['Quelles compétences manquent ?', 'Quelles formations recommandez-vous ?', 'Qui mérite une promotion ?'];
    sources     = [
      { label: 'GET /api/chatbot/find?nom=' + encodeURIComponent(data.nom || ''), type: 'api' },
      { label: 'GET /api/chatbot/promotion/' + (data.id || ''), type: 'api' }
    ];
    cards = [{
      type: 'promotion', rank: 1,
      data: {
        id: data.id, nom: data.nom, grade, gradeActuel: grade, gradeCible: cible,
        score: scoreSur5(score), scorePromotion: score,
        readinessScore: score, readinessPercentage: score,
        readinessLabel: labelFromScore(score),
        delaiEstime: data.delaiEstime,
        competencesAcquises: acq, competencesManquantes: manq
      }
    }];

    newCtx.lastCollaborateurId  = data.id;
    newCtx.lastCollaborateurNom = data.nom;
    newCtx.lastScorePromotion   = score;
    newCtx.lastGrade            = grade;

  } else {
    const promo = (data.collaborateurs || []).map(p => {
      const s = toNum(p.scorePromotion);
      return Object.assign({}, p, {
        scorePromotion: s, readinessScore: s, readinessPercentage: s,
        gradeActuel: p.gradeActuel || p.grade || '',
        gradeCible:  p.gradeCible  || p.prochainGrade || '',
        scoreSur5:   scoreSur5(s)
      });
    });
    const top = promo[0];

    answer   = promo.length > 0
      ? promo.length + ' collaborateur(s) prêt(s) pour une promotion.'
      : 'Aucun collaborateur n\'atteint le seuil (scorePromotion ≥ 60/100).';
    analysis = top
      ? 'Profil le plus prêt : ' + top.nom + ' (' + top.gradeActuel + (top.gradeCible ? ' → ' + top.gradeCible : '') + ', ' + top.departement + ') — readiness : ' + top.scorePromotion + '/100.'
      : '';
    reasoning = [
      'Critère : scorePromotion ≥ 60/100',
      promo.length + ' collaborateur(s) éligibles',
      top ? 'Premier candidat : ' + top.nom + ' — ' + top.scorePromotion + '/100' : 'Aucun profil éligible'
    ];
    actions     = ['Simuler la readiness promotion', 'Voir le parcours carrière', 'Planifier un entretien'];
    suggestions = [
      top ? 'Quel est le readiness de ' + top.nom + ' ?' : 'Montrez les hauts potentiels',
      'Quelles compétences manquent ?', 'Quelles formations recommandez-vous ?'
    ];
    sources = [{ label: 'GET /api/chatbot/promotables', type: 'api' }];
    cards   = promo.slice(0, 5).map((p, i) => ({
      type: 'promotion', rank: i + 1,
      data: {
        nom: p.nom, poste: p.poste, grade: p.gradeActuel,
        gradeActuel: p.gradeActuel, gradeCible: p.gradeCible,
        departement: p.departement, score: p.scoreSur5,
        scorePromotion: p.scorePromotion, readinessScore: p.scorePromotion,
        readinessPercentage: p.scorePromotion, readinessLabel: labelFromScore(p.scorePromotion)
      }
    }));
    if (top) { newCtx.lastCollaborateurId = top.id; newCtx.lastCollaborateurNom = top.nom; }
  }
}

// ════════════════════════════════════════════════════════════════════════════
// TALENT
// ════════════════════════════════════════════════════════════════════════════
else if (branch === 'TALENT') {
  const talents = data.talents || [];
  const top     = talents[0];
  const nom0    = top ? (top.Nom || top.nom || '') : '';
  const grd0    = top ? (top.Grade || top.grade || '') : '';
  const dpt0    = top ? (top.Departement || top.departement || '') : '';
  const sc0     = top ? (top.MoyenneCompetences || top.moyenneCompetences || 0) : 0;

  answer   = talents.length > 0
    ? talents.length + ' haut(s) potentiel(s) identifié(s).'
    : 'Aucun haut potentiel identifié (seuil ≥ 4/5).';
  analysis = top ? 'Meilleur profil : ' + nom0 + ' (' + grd0 + ', ' + dpt0 + ') — score ' + sc0 + '/5.' : '';
  reasoning = [
    'Seuil haut potentiel : moyenne compétences ≥ 4.0/5',
    talents.length + ' collaborateur(s) atteignent ce seuil',
    top ? 'Score maximum : ' + sc0 + '/5 — ' + nom0 : 'Aucun collaborateur au-dessus du seuil'
  ];
  actions     = ['Voir la matrice 9-Box', 'Planifier une revue talent', 'Lancer un plan de succession'];
  suggestions = ['Qui est prêt pour une promotion ?', 'Quels postes sont sans successeur ?', 'Montrez les postes à risque'];
  sources     = [{ label: 'GET /api/chatbot/hr-talent', type: 'api' }];
  cards       = talents.slice(0, 5).map((t, i) => ({
    type: 'collaborateur', rank: i + 1,
    data: {
      id:          t.id   || t.Id          || null,
      nom:         t.Nom  || t.nom         || '',
      grade:       t.Grade || t.grade      || '',
      departement: t.Departement || t.departement || '',
      score:       t.MoyenneCompetences || t.moyenneCompetences || 0,
      badge:       (t.MoyenneCompetences || t.moyenneCompetences || 0) >= 4.5
                   ? 'Talent stratégique' : 'Haut potentiel'
    }
  }));
  if (top) {
    newCtx.lastCollaborateurId  = top.id || top.Id || null;
    newCtx.lastCollaborateurNom = nom0;
  }
}

// ════════════════════════════════════════════════════════════════════════════
// FORMATION_SIMULATION
// ════════════════════════════════════════════════════════════════════════════
else if (branch === 'FORMATION_SIMULATION') {
  if (data.__notFound) {
    answer      = 'Collaborateur introuvable : "' + (data.nomRecherche || '') + '".';
    reasoning   = ['GET /api/chatbot/find — aucun résultat pour ce nom'];
    suggestions = ['Quelles formations recommandez-vous ?', 'Montrez les hauts potentiels'];
    sources     = [{ label: 'GET /api/chatbot/find', type: 'api' }];

  } else if (data.__noName) {
    answer      = 'Précisez le nom du collaborateur à simuler.';
    reasoning   = ['Aucun nom détecté dans la question'];
    suggestions = ['Exemple : "Si je forme Amine Jebali sur Leadership niveau 4"'];

  } else {
    const avant = toNum(data.scoreAvant);
    const apres = toNum(data.scoreApres);
    const gain  = toNum(data.gain);
    const comp  = data.competenceSimulee || data.detectedCompetence || '';
    const niv   = data.niveauSimule      || data.detectedNiveau     || '';

    answer   = (data.collaborateurNom || data.nom || '') + ' — Couverture : ' + avant + '% → ' + apres + '% après ' + comp + ' niveau ' + niv + ' (gain : +' + gain + '%).';
    analysis = data.impact || '';
    reasoning = [
      'Workflow : /find → /collaborateur/{id} → /simulate-formation',
      'Poste cible : ' + (data.posteCible || ''),
      'Compétence simulée : ' + comp + ' niveau ' + niv,
      'Score avant : ' + avant + '% — Score après : ' + apres + '%',
      'Gain de couverture : +' + gain + '%',
      data.recommandation || null
    ].filter(Boolean);
    actions     = ['Planifier la formation', 'Voir le plan de développement complet', 'Exporter le rapport'];
    suggestions = [
      'Quel est son readiness pour une promotion ?',
      'Qui peut remplacer ' + (data.collaborateurNom || data.nom || '') + ' ?',
      'Quelles formations recommandez-vous ?'
    ];
    sources = [
      { label: 'GET /api/chatbot/find',                                   type: 'api' },
      { label: 'GET /api/chatbot/collaborateur/' + (data.id || ''),       type: 'api' },
      { label: 'GET /api/chatbot/simulate-formation',                     type: 'api' }
    ];
    cards = [{
      type: 'simulation',
      data: {
        collaborateurNom: data.collaborateurNom || data.nom || '',
        posteCible:       data.posteCible || '',
        competence:       comp,
        niveauSimule:     niv,
        scoreAvant:       avant,
        scoreApres:       apres,
        gain,
        impact:           data.impact        || '',
        recommandation:   data.recommandation || ''
      }
    }];

    newCtx.lastCollaborateurId   = data.id  || null;
    newCtx.lastCollaborateurNom  = data.collaborateurNom || data.nom || null;
    newCtx.lastPoste             = data.posteCible || null;
    newCtx.lastCompetenceSimulee = comp;
  }
}

// ════════════════════════════════════════════════════════════════════════════
// FORMATION_SIM_INCOMPLETE
// ════════════════════════════════════════════════════════════════════════════
else if (branch === 'FORMATION_SIM_INCOMPLETE') {
  answer    = 'Pour simuler une formation, précisez la compétence et le niveau cible.';
  analysis  = 'Exemple : "Si je forme Amine Jebali sur Leadership niveau 4"';
  reasoning = ['Compétence ou niveau non détecté dans la question'];
  actions     = ['Reformuler la question avec compétence + niveau'];
  suggestions = [
    'Si je forme Amine Jebali sur Leadership niveau 4',
    'Quelles formations recommandez-vous ?',
    'Montrez les compétences manquantes'
  ];
}

// ════════════════════════════════════════════════════════════════════════════
// POSTES_CRITIQUES
// ════════════════════════════════════════════════════════════════════════════
else if (branch === 'POSTES_CRITIQUES') {
  const risques = data.collaborateurs || [];
  const eleve   = risques.filter(r => r.niveauRisque === 'Élevé');
  const moyen   = risques.filter(r => r.niveauRisque === 'Moyen');

  answer = risques.length > 0
    ? risques.length + ' poste(s) à risque — ' + eleve.length + ' risque élevé, ' + moyen.length + ' risque moyen.'
    : 'Aucun poste à risque détecté.';
  reasoning = [
    'Seuils par grade : Junior=2.0, Senior=3.0, Manager=3.5, Director/SM=4.0, Partner=4.5',
    'Risque élevé : score < seuil ET ancienneté > 2 ans',
    eleve.length + ' poste(s) en risque élevé'
  ];
  actions     = ['Lancer un plan de développement', 'Planifier des évaluations', 'Voir les formations prioritaires'];
  suggestions = ['Qui peut remplacer ces collaborateurs ?', 'Quelles formations recommandez-vous ?', 'Montrez les hauts potentiels'];
  sources     = [{ label: 'GET /api/chatbot/postes-a-risque', type: 'api' }];
  cards       = risques.slice(0, 5).map(r => ({
    type: 'alerte',
    data: {
      nom: r.nom, poste: r.poste, grade: r.grade, departement: r.departement,
      scoreActuel: r.scoreActuel, seuilAttendu: r.seuilAttendu,
      ecart: r.ecart, niveauRisque: r.niveauRisque, anciennete: r.anciennete
    }
  }));
}

// ════════════════════════════════════════════════════════════════════════════
// FORMATION
// ════════════════════════════════════════════════════════════════════════════
else if (branch === 'FORMATION') {
  const s = data;
  answer   = (s.formationsEnCours || 0) + ' formation(s) en cours — Taux de complétion : ' + (s.tauxCompletion || 0) + '%.';
  analysis = 'Sur ' + (s.totalInscriptions || 0) + ' inscriptions, ' + (s.terminees || 0) + ' terminées.';
  reasoning = [
    (s.formationsEnCours || 0) + ' formation(s) actuellement en cours',
    (s.terminees || 0) + ' formation(s) complétée(s)',
    'Taux de complétion global : ' + (s.tauxCompletion || 0) + '%'
  ];
  actions     = ['Voir le catalogue de formations', 'Accéder aux recommandations', 'Voir les certifications'];
  suggestions = ['Si je forme quelqu\'un sur une compétence ?', 'Montrez les compétences manquantes', 'Qui mérite une promotion ?'];
  sources     = [{ label: 'GET /api/chatbot/stats', type: 'api' }];
  cards       = [{ type: 'analytics', data: { kpis: [
    { label: 'Formations en cours', value: s.formationsEnCours  || 0, icon: 'fa-book' },
    { label: 'Terminées',           value: s.terminees          || 0, icon: 'fa-check-circle' },
    { label: 'Total inscriptions',  value: s.totalInscriptions  || 0, icon: 'fa-user-graduate' },
    { label: 'Taux complétion',     value: (s.tauxCompletion || 0) + '%', icon: 'fa-chart-pie' }
  ]}}];
}

// ════════════════════════════════════════════════════════════════════════════
// ANALYTICS
// ════════════════════════════════════════════════════════════════════════════
else if (branch === 'ANALYTICS') {
  const s  = data;
  const d5 = (s.repartitionDept  || []).slice(0, 5);
  const c5 = (s.topCompetences   || []).slice(0, 5);

  answer = 'Organisation : ' + (s.collaborateursActifs || 0) + ' collaborateur(s) actif(s) — '
    + (s.formationsEnCours || 0) + ' formation(s) — '
    + (s.tauxCompletion || 0) + '% complétion.';
  reasoning = [
    'Source : données SIRH EY en temps réel',
    (s.collaborateursActifs || 0) + ' collaborateur(s) actifs',
    (s.formationsEnCours || 0) + ' formation(s) en cours',
    'Taux de complétion : ' + (s.tauxCompletion || 0) + '%'
  ];
  actions     = ['Voir le tableau de bord RH', 'Accéder aux insights', 'Exporter un rapport'];
  suggestions = ['Quels sont les hauts potentiels ?', 'Qui est prêt pour une promotion ?', 'Quels postes sont sans successeur ?'];
  sources     = [{ label: 'GET /api/chatbot/stats', type: 'api' }];
  cards       = [{ type: 'analytics', data: {
    kpis: [
      { label: 'Collaborateurs actifs', value: s.collaborateursActifs || 0, icon: 'fa-users' },
      { label: 'Formations en cours',   value: s.formationsEnCours   || 0, icon: 'fa-book' },
      { label: 'Taux complétion',       value: (s.tauxCompletion || 0) + '%', icon: 'fa-chart-pie' },
      { label: 'Terminées',             value: s.terminees           || 0, icon: 'fa-check-circle' }
    ],
    departments:    d5.map(d => ({ label: d.departement, value: d.total })),
    topCompetences: c5.map(c => ({ label: c.nom, value: c.niveauMoyen, count: c.nbCollaborateurs }))
  }}];
}

// ════════════════════════════════════════════════════════════════════════════
// FALLBACK
// ════════════════════════════════════════════════════════════════════════════
else {
  answer    = 'Je peux vous aider avec la succession, les promotions, les hauts potentiels, la simulation de formations ou les postes à risque.';
  reasoning = ['Question non reconnue — liste des capacités affichée'];
  suggestions = [
    'Qui peut remplacer [prénom nom] ?',
    'Quel est le readiness de [prénom nom] ?',
    'Quels sont les hauts potentiels ?'
  ];
}

return [{ json: {
  answer,
  analysis:        analysis  || null,
  reasoning:       reasoning.filter(Boolean),
  actions:         actions   || [],
  suggestions:     suggestions || [],
  sources:         sources   || [],
  cards:           cards     || [],
  executionHistory,
  context:         newCtx
}}];
